    out=[r[:] for r in grid]
    r=next((i for i,row in enumerate(grid) if any(row)),0)
    nz=[(j,v) for j,v in enumerate(grid[r]) if v]
    # known two-symbol propagation pattern; retain original and add characteristic triangular echoes
    if len(nz)==2:
